	valid := map[string]any{"enabled": true, "provider": "momento", "momentoUrl": "https://momento.corp.example", "momentoSiteId": "agenthub", "momentoProxy": true, "placement": "head", "includeAdmin": false}
	if err := server.validateSetting(request, tracking.SettingKey, valid, nil); err != nil {
		t.Fatalf("a valid configuration was rejected: %v", err)
	}
	for name, value := range map[string]map[string]any{
		"oversized snippet": {"enabled": true, "provider": "custom", "customSnippet": strings.Repeat("x", tracking.MaxSnippetBytes+1)},
		"unknown provider":  {"enabled": true, "provider": "piwik"},
		"unknown field":     {"enabled": false, "unsafeInline": true},
		"wrong type":        {"enabled": "yes"},
	} {
		if err := server.validateSetting(request, tracking.SettingKey, value, nil); err == nil {
			t.Errorf("%s was accepted", name)
		}
	}
	// A key the console did not send keeps its default rather than becoming
	// false: the proxy is the recommended shape and stays on unless turned off.
	decoded, err := decodeTrackingSettings(map[string]any{"enabled": true, "provider": "momento", "momentoUrl": "https://m.corp.example", "momentoSiteId": "x"})
	if err != nil || !decoded.MomentoProxy || decoded.Placement != "head" {
		t.Errorf("defaults were not kept for absent keys: %+v %v", decoded, err)
	}
}
	s.trackingMu.Lock()
	s.trackingUntil = time.Time{}
	s.trackingMu.Unlock()
}

// decodeTrackingSettings re-reads a submitted document into its typed form,
// starting from the defaults so a key the console did not send keeps its
// default rather than becoming false or empty.
func decodeTrackingSettings(value map[string]any) (tracking.Settings, error) {
	settings := tracking.Defaults()
	raw, err := json.Marshal(value)
	if err != nil {
		return settings, err
	}
	decoder := json.NewDecoder(bytes.NewReader(raw))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&settings); err != nil {
		return settings, errors.New("방문 추적 설정 형식을 확인해 주세요")
	}
	return settings, nil
}

// pagePolicy is the base policy plus what the snippet needs: the nonce, the
// snippet's origins, and — while tracking is on — an address for the browser
// to report what it refused to. Every addition is tied to the request or to
// the current settings, so switching tracking off returns the exact base.
func pagePolicy(settings tracking.Settings, nonce string) string {
	sources := settings.PolicySources()
	scripts := append([]string{"'self'", "'nonce-" + nonce + "'"}, sources.Scripts...)
	connects := append([]string{"'self'", "ws:", "wss:"}, sources.Connects...)
	images := append([]string{"'self'", "data:"}, sources.Images...)
	return "default-src 'self'; img-src " + strings.Join(images, " ") +
		"; style-src 'self' 'unsafe-inline'; font-src 'self'; connect-src " + strings.Join(connects, " ") +
		"; script-src " + strings.Join(scripts, " ") +
		"; frame-ancestors 'none'; base-uri 'self'; form-action 'self'; report-uri " + tracking.ReportPath
}

// newNonce mints the per-request value that ties the injected script tags to
// the policy header of the same response.
func newNonce() string {
	var raw [16]byte
	if _, err := rand.Read(raw[:]); err != nil {
		panic("crypto/rand unavailable: " + err.Error())
	}
	return base64.StdEncoding.EncodeToString(raw[:])
}

// serveIndex serves the single-page shell for pagePath. With tracking off it
// is the file as built; with tracking on for this page the snippet is written
// in with a fresh nonce and the policy header names the same nonce.
func (s *Server) serveIndex(w http.ResponseWriter, r *http.Request, pagePath string) {
	settings := s.cachedTrackingSettings(r.Context())
	if !settings.Active(pagePath) {
		http.ServeFileFS(w, r, s.static, "index.html")
		return
	}
	page, err := fs.ReadFile(s.static, "index.html")
	if err != nil {
		http.NotFound(w, r)
		return
	}
		return
	}
	// One origin, and the one the list will hold. The allow list is stored as a
	// single string that every reader splits on a comma, a space, a tab or a
	// newline, so a value with any of those in it is a list and not the one entry
	// this route offers to add: appended as it arrived it became two entries,
	// which is a second origin in the policy header of every page that nobody
	// clicked for. The settings form is the route for a list and is left to take
	// one; tracking.SingleHost is asked here and nowhere else.
	origin, single := tracking.SingleHost(input.Origin)
	if !single || !strings.HasPrefix(strings.ToLower(origin), "http") {
		writeError(w, http.StatusBadRequest, "invalid_origin", "허용할 출처는 https://호스트 형태여야 하며, 한 번에 한 곳만 더할 수 있습니다.")
		return
	}
	settings := tracking.Defaults()
	if err := s.store.Setting(r.Context(), tracking.SettingKey, &settings); err != nil && !errors.Is(err, store.ErrNotFound) {
		writeStoreError(w, err)
		return
	}
	settings = settings.Normalized()
	// An origin the list already holds leaves it exactly as it was — AddAllowedHost
	// matches case-insensitively and hands back what it was given. The response
	// stays a 200 carrying the list, because the console's screen reads it to
	// refresh and a click on an origin somebody else already allowed is not an
	// error. The trail, though, has to tell the two apart: without this flag every
	// click left an identical "success" row whether or not the list grew, so the
	// trail could not answer when the list last changed. The row is still written
	// in the unchanged case rather than dropped, since what an administrator did
	// is worth recording even when it turned out to be a no-op.
	updated := tracking.AddAllowedHost(settings.AllowedHosts, origin)
	added := updated != settings.AllowedHosts
	settings.AllowedHosts = updated
	if err := settings.Validate(); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_setting", err.Error())
		return
	}
	if err := s.store.PutSetting(r.Context(), tracking.SettingKey, settings, nil, u.ID); err != nil {
		writeStoreError(w, err)
		return
	}
	s.invalidateTrackingSettings()
	// origin is what SingleHost read out of the request, which is the entry as the
	// list stores it — trimmed, without a trailing slash — so the row can be read
	// against the list rather than against whatever the console happened to post.
	s.store.Audit(r.Context(), &u, "settings.update", "setting", tracking.SettingKey, "success", clientIP(r), map[string]any{"keys": []string{"allowedHosts"}, "origin": origin, "added": added})
	writeJSON(w, http.StatusOK, map[string]any{"allowedHosts": settings.AllowedHosts})
}
		if err != nil {
			return err
		}
		return settings.Validate()
	case runtimeenv.SettingKey:
		// Everything here ends up in a Pod spec, so it is checked against the same
		// rules the operator enforces rather than stored and quietly dropped later.
		settings, err := decodeRuntimeEnvironment(value)
		if err != nil {
			return err
		}
		return settings.Validate()
	case runtimetype.SettingKey:
		settings, err := decodeRuntimeAgentSettings(value)
		if err != nil {
			return err
		}
		return settings.Validate()
	case tracking.SettingKey:
		// A snippet that cannot work — a provider with no id, a pasted block past
		// the size limit — is refused here, where the form can say so, rather
		// than stored and discovered as an empty dashboard.
		settings, err := decodeTrackingSettings(value)
		if err != nil {
			return err
		}
		return settings.Validate()
	case mail.SettingKey:
		// A relay these settings cannot reach is refused at the form rather than
		// discovered as a list of failed deliveries.
		settings, err := decodeMailSettings(value)
		if err != nil {
			return err
		}
		return settings.Validate()
	}
	return nil
}

func decodeRuntimeAgentSettings(value map[string]any) (runtimetype.Settings, error) {
	var settings runtimetype.Settings
	raw, err := json.Marshal(value)
	if err != nil {
		return settings, err
	}
	decoder := json.NewDecoder(bytes.NewReader(raw))

	switch letter {
	case '"', '\'', '`', '<', '>', ' ', '\t', '\n', '\r', ')', ',', ';', '\\', '+':
		return true
	}
	return false
}

// originOf reduces an address to scheme://host[:port], which is what a policy
// source is.
func originOf(raw string) string {
	parsed, err := url.Parse(strings.TrimSpace(raw))
	if err != nil || parsed.Host == "" {
		return ""
	}
	scheme := parsed.Scheme
	if scheme == "" {
		scheme = "https"
	}
	return scheme + "://" + parsed.Host
}

func splitHosts(list string) []string {
